using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests {
 public sealed class RewardPresentationTests {
  GameRuntime game;string dir;int frame;List<float> times=new List<float>();List<string> segments=new List<string>();const string Frames="/tmp/idle-design6-rewards";string recording=Frames;const string Images="/tmp/idle-design6-review";
  [UnitySetUp]public IEnumerator Setup(){recording=Frames;frame=0;times.Clear();segments.Clear();dir=Path.Combine(Path.GetTempPath(),"idle-receipt-review-"+Guid.NewGuid());Directory.CreateDirectory(dir);Directory.CreateDirectory(Frames);Directory.CreateDirectory(Images);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();game.Act(s=>NarrativeBridge.Action(s,"name","AURA"));for(int i=0;i<5;i++)game.Act(s=>NarrativeBridge.Action(s,"continue"));game.Act(s=>NarrativeBridge.Action(s,"skip-tutorial"));game.Act(s=>{var n=s.Copy();n.Legacy.prepared=true;n.Story.enabled=false;n.Story.open=null;n.Story.queue=Array.Empty<string>();n.Story.seen=NarrativeCatalog.Dialogues.Select(d=>d.Id).ToArray();n.Story.tutorial="skipped";n.Retention.gems=100000;n.Credits=ScientificNumber.From(50000);n.Hardware[0]=10;n.Prestige.resets=1;n.Prestige.Total=ScientificNumber.From(1000);n.Prestige.lab=true;n.Workshop.components=Enumerable.Repeat(500L,ItemBalance.ComponentIds.Length).ToArray();n.Missions.season.xp=50000;return n;});game.Show("hardware");yield return null;game.Audio.Unlock();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;}
  Button B(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);return b;}
  void Click(string name){var b=B(name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  RewardStage Current=>game.GetComponent<RewardPresentation>().Current;
  void Saved(){var loaded=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(loaded.Writable,Is.True,loaded.Message);Assert.That(loaded.State.Capsules.draws,Is.EqualTo(game.State.Capsules.draws));Assert.That(loaded.State.Rewards.shopRevision,Is.EqualTo(game.State.Rewards.shopRevision));Assert.That(loaded.State.Retention.gems,Is.EqualTo(game.State.Retention.gems));CollectionAssert.AreEqual(game.State.Workshop.components,loaded.State.Workshop.components);}
  IEnumerator Record(string name,float seconds,Action action,Button press=null){int start=frame;float began=Time.realtimeSinceStartup;bool done=false,pressed=false;while(Time.realtimeSinceStartup-began<seconds){if(press!=null&&!pressed&&Time.realtimeSinceStartup-began>.43f){var e=new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left};ExecuteEvents.Execute(press.gameObject,e,ExecuteEvents.pointerDownHandler);pressed=true;}if(!done&&Time.realtimeSinceStartup-began>.55f){if(press!=null)ExecuteEvents.Execute(press.gameObject,new PointerEventData(EventSystem.current){button=PointerEventData.InputButton.Left},ExecuteEvents.pointerUpHandler);action?.Invoke();done=true;}times.Add(Time.realtimeSinceStartup);WorkshopTests.Capture(402,874,recording+"/"+(frame++).ToString("D4")+".png");yield return null;}segments.Add(name+" "+start+" "+(frame-1));}
  void ScrollTo(string name){Canvas.ForceUpdateCanvases();var scroll=game.Content.GetComponentInParent<ScrollRect>();var target=(RectTransform)GameObject.Find(name).transform;float y=-((RectTransform)game.Content).InverseTransformPoint(target.TransformPoint(target.rect.center)).y;scroll.verticalNormalizedPosition=Mathf.Clamp01(1-(y-scroll.viewport.rect.height*.35f)/Mathf.Max(1,((RectTransform)game.Content).rect.height-scroll.viewport.rect.height));Canvas.ForceUpdateCanvases();}
  [UnityTest]public IEnumerator RecordChestCapsuleShopAndLivingLabor(){recording=Frames;frame=0;times.Clear();segments.Clear();var listener=game.GetComponent<AudioListener>();if(listener!=null)listener.enabled=false;var node=new GameObject("ReceiptAudioListener",typeof(AudioListener));node.transform.SetParent(game.transform);var audio=node.AddComponent<ReviewAudioCapture>();audio.Begin();yield return Record("08-living-labor",12,null);game.Show("market");yield return null;ScrollTo("MarketOffer-free-common");yield return Record("09-free-chest",4.8f,()=>{Click("MarketOffer-free-common");Saved();Assert.That(Current.ReceiptKey,Is.EqualTo("shop:"+game.State.Rewards.receipt.id));},B("MarketOffer-free-common"));Assert.That(Current.IsAnimating,Is.False);Assert.That(game.State.Rewards.receipt.payment,Is.EqualTo("free"));
   ScrollTo("MarketOffer-chest:rare");yield return Record("10-paid-chest",4.8f,()=>{Click("MarketOffer-chest:rare");Saved();Assert.That(game.State.Rewards.receipt.payment,Is.EqualTo("gems"));},B("MarketOffer-chest:rare"));Assert.That(Current.IsAnimating,Is.False);
   Click("MarketMaterials");yield return null;var offer=Market.Offers(game.State).First(o=>o.Kind=="material"&&!o.Stock&&Market.Quote(game.State,o.Id).Allowed);ScrollTo("MarketOffer-"+offer.Id);yield return Record("11-shop-material",3.5f,()=>{Click("MarketOffer-"+offer.Id);Saved();Assert.That(Current.RewardCount,Is.EqualTo(1));},B("MarketOffer-"+offer.Id));
   game.Show("gems");yield return null;Click("GemPage-capsule");yield return null;ScrollTo("CapsuleDraw");yield return Record("12-gumball",5,()=>{Click("CapsuleDraw");Saved();Assert.That(Current.ReceiptKey,Is.EqualTo("capsule:"+game.State.Capsules.draws));},B("CapsuleDraw"));Assert.That(Current.IsAnimating,Is.False);Assert.That(game.State.Capsules.draws,Is.EqualTo(1));
   game.Show("seasons");yield return null;Click("SeasonReward-5");yield return null;ScrollTo("SeasonChest-1");yield return Record("13-season-chest",4.8f,()=>{Click("SeasonChest-1");Saved();Assert.That(game.State.Rewards.receipt.payment,Is.EqualTo("season"));},B("SeasonChest-1"));game.Act(s=>{var n=s.Copy();n.Industry.families[0]=true;foreach(var task in n.Missions.daily.tasks)if(string.IsNullOrEmpty(task.objective)){var field=typeof(LifetimeState).GetField(task.metric);field.SetValue(n.Lifetime,Math.Max((double)field.GetValue(n.Lifetime),task.baseline+task.goal));}return n;});game.Show("missions");yield return null;Click("MissionBonus");yield return null;var box=game.State.Missions.boxes.pending.Last();int family=box.choices.First().family;string button="OpenBonusBox-"+box.id+"-"+family;ScrollTo(button);yield return Record("14-earned-bonus-box",4.8f,()=>{Click(button);Saved();Assert.That(Current.ReceiptKey,Is.EqualTo("bonus:"+box.id));Assert.That(game.State.Missions.boxes.opened,Is.EqualTo(1));},B(button));Assert.That(File.Exists(Frames+"/"+(frame-1).ToString("D4")+".png"),Is.True,"Entire native frame range belongs to this recording, independent of fixture execution order");audio.Save(Frames);File.WriteAllLines(Frames+"/times.txt",times.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));File.WriteAllLines(Frames+"/segments.txt",segments);}

  [UnityTest]public IEnumerator RecordActualMenuWalkWithScrollAndReturn(){recording="/tmp/idle-design6-menus";Directory.CreateDirectory(recording);frame=0;times.Clear();segments.Clear();var listener=game.GetComponent<AudioListener>();if(listener!=null)listener.enabled=false;var node=new GameObject("MenuAudioListener",typeof(AudioListener));node.transform.SetParent(game.transform);var audio=node.AddComponent<ReviewAudioCapture>();audio.Begin();foreach(var lang in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",lang));foreach(string route in new[]{"settings","production","storage","profile","company","missions","seasons","market","gems","ads","store","progress","story","challenges","goals","models"}){game.Show("hardware");game.GetComponent<GameMenu>().Open();yield return null;Click("Menu-"+route);yield return null;yield return Record("menu-"+route+"-"+lang+"-top",1.1f,null);var scroll=game.Content.GetComponentInParent<ScrollRect>();scroll.verticalNormalizedPosition=0;yield return Record("menu-"+route+"-"+lang+"-bottom",1.1f,null);Click("MenuReturn");Assert.That(game.CurrentTab,Is.EqualTo("hardware"));yield return null;}}audio.Save(recording);File.WriteAllLines(recording+"/times.txt",times.Select(t=>t.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));File.WriteAllLines(recording+"/segments.txt",segments);}
  [UnityTest]public IEnumerator IntegratedVoucherAndCompanyPathsKeepActualSavedReceipts(){game.Act(s=>{var n=s.Copy();n.Prestige.Total=ScientificNumber.From(1000);n.Rewards.vouchersEarned=1;return n;});game.GetComponent<GameMenu>().Open();yield return null;Click("Menu-company");yield return null;Assert.That(game.CurrentTab,Is.EqualTo("company"));Click("MenuReturn");Assert.That(game.CurrentTab,Is.EqualTo("hardware"));game.Show("gems");yield return null;Click("GemPage-capsule");yield return null;Click("CapsuleVoucher");Saved();Assert.That(game.State.Capsules.last.payment,Is.EqualTo("voucher"));Assert.That(game.State.Rewards.vouchersSpent,Is.EqualTo(1));Assert.That(Current.ReceiptKey,Is.EqualTo("capsule:"+game.State.Capsules.draws));Current.Cancel();yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Rewards.vouchersSpent,Is.EqualTo(1));Assert.That(game.GetComponent<RewardPresentation>().Current,Is.Null);}
  [UnityTest]public IEnumerator ReceiptCancelReducedRepeatUnavailableAndReloadDoNotGrant(){game.Show("market");yield return null;Click("MarketOffer-free-common");var count=game.State.Rewards.shopRevision;Saved();Current.Cancel();Assert.That(game.State.Rewards.shopRevision,Is.EqualTo(count));var q=Market.Quote(game.State,"free-common");Assert.That(q.Allowed,Is.False);Assert.That(game.Act(s=>Market.Buy(s,q.Ticket)),Is.False);game.Show("gems");yield return null;Click("GemPage-capsule");yield return null;Click("CapsuleVideo");yield return null;Assert.That(game.State.Capsules.draws,Is.Zero);Assert.That(game.State.Capsules.videos,Is.Zero);Assert.That(Current.gameObject.activeSelf,Is.False);Click("CapsuleDraw");Saved();Current.ShortenButton.onClick.Invoke();yield return new WaitForSecondsRealtime(.6f);Assert.That(Current.IsAnimating,Is.False);long draws=game.State.Capsules.draws;game.Act(s=>SettingsRules.Change(s,"toggle-effects"));yield return null;Click("CapsuleDraw");Assert.That(game.State.Capsules.draws,Is.EqualTo(draws+1));Assert.That(Current.IsAnimating,Is.False);Assert.That(Current.gameObject.activeSelf,Is.True);Current.CloseButton.onClick.Invoke();Saved();yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Capsules.draws,Is.EqualTo(draws+1));Assert.That(game.GetComponent<RewardPresentation>().Current,Is.Null,"Reload never replays or grants the last receipt");}

  [UnityTest]public IEnumerator SharedForgePoolAndBackgroundCancelKeepReceipts(){string type=ItemBalance.Items.First(d=>d.Starter==0).Id;game.Act(s=>{var n=s.Copy();n.Workshop.learned=Enumerable.Repeat(true,ItemBalance.Items.Length).ToArray();n.Data=ScientificNumber.From(1e20);return n;});game.Show("items");yield return null;var ui=game.WorkshopView;ui.SelectRecipe(Workshop.Index(type));ui.Primary.onClick.Invoke();yield return null;var sequence=UnityEngine.Object.FindFirstObjectByType<ForgeSequence>();int id=sequence.GetInstanceID();ui.Forge.Shorten();yield return new WaitForSecondsRealtime(1);Assert.That(ui.Forge.IsAnimating,Is.False);ui.Primary.onClick.Invoke();yield return null;Assert.That(UnityEngine.Object.FindFirstObjectByType<ForgeSequence>().GetInstanceID(),Is.EqualTo(id),"Shared presentation is reused");Assert.That(sequence.GetComponentsInChildren<Button>(true).Count(b=>b.name=="ShortenReceipt"),Is.EqualTo(1));Assert.That(sequence.GetComponentsInChildren<Image>(true).Count(i=>i.name.StartsWith("DirectedPixel")),Is.EqualTo(18));Saved();long items=game.State.Workshop.inventory.Length;game.SendMessage("OnApplicationPause",true);Assert.That(ui.Forge.IsAnimating,Is.False);Assert.That(game.State.Workshop.inventory.Length,Is.EqualTo(items));game.SendMessage("OnApplicationPause",false);Saved();}
  [UnityTest]public IEnumerator HardwareQuotesAndAllMenusAtMobileSizes(){foreach(var language in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",language));foreach(string mode in new[]{"1","10","max"}){game.Act(s=>SettingsRules.Change(s,"buy-mode",mode));game.Show("hardware");yield return null;foreach(int w in new[]{320,390,430,402}){WorkshopTests.Capture(w,w==320?568:w==390?844:w==430?932:874,Images+"/hardware-"+mode+"-"+language+"-"+w+".png");var price=GameObject.Find("hardware-calculator/PurchaseCost/HardwarePrice/CostAmount").GetComponent<Text>();Assert.That(price.text,Does.Not.Contain("/"));long qty=SettingsRules.BuyQuantity(game.State,0);Assert.That(price.text,Is.EqualTo(NumberFormatting.Format(qty>0?Game.HardwareCost(game.State,0,qty):ScientificNumber.Zero,game.State.Settings.numberFormat,game.State.Settings.language)));yield return null;}}
   foreach(string route in new[]{"settings","production","storage","profile","company","missions","seasons","market","gems","ads","store","progress","story","challenges","goals","models"}){game.Show("hardware");game.GetComponent<GameMenu>().Open();yield return null;Click("Menu-"+route);yield return new WaitForSecondsRealtime(.12f);Assert.That(game.CurrentTab,Is.EqualTo(route));if(route=="settings")for(int l=0;l<SettingsCatalog.Languages.Length;l++)Assert.That(GameObject.Find("Language-"+SettingsCatalog.Languages[l]).GetComponentInChildren<Text>().text,Is.EqualTo(SettingsCatalog.LanguageNames[l]+(language==SettingsCatalog.Languages[l]?" ✓":"")),"Language choices retain distinct original names instead of all translating to the selected language");foreach(int w in new[]{320,390,430}){WorkshopTests.Capture(w,w==320?568:w==390?844:932,Images+"/menu-"+route+"-"+language+"-"+w+".png");yield return null;}var scroll=game.Content.GetComponentInParent<ScrollRect>();scroll.verticalNormalizedPosition=0;yield return null;WorkshopTests.Capture(320,568,Images+"/menu-"+route+"-"+language+"-320-bottom.png");Click("MenuReturn");Assert.That(game.CurrentTab,Is.EqualTo("hardware"));yield return null;}}
  }
  [UnityTest]public IEnumerator ReceiptScreensAtDEENMobileAndSimulatedPhoneSafeArea(){foreach(var lang in new[]{"de","en"}){game.Act(s=>SettingsRules.Change(s,"language",lang));game.Show("market");yield return null;Click("MarketOffer-chest:legendary");yield return new WaitForSecondsRealtime(1.65f);foreach(int w in new[]{320,390,430,402}){WorkshopTests.Capture(w,w==320?568:w==390?844:w==430?932:874,Images+"/chest-"+lang+"-"+w+".png");}Current.Cancel();game.Show("gems");yield return null;Click("GemPage-capsule");yield return null;Click("CapsuleDraw");yield return new WaitForSecondsRealtime(.83f);WorkshopTests.Capture(402,874,Images+"/capsule-"+lang+"-402.png");Current.Cancel();game.Show("hardware");foreach(var safe in UnityEngine.Object.FindObjectsByType<SafeArea>(FindObjectsSortMode.None)){safe.enabled=false;var r=(RectTransform)safe.transform;r.anchorMin=new Vector2(0,34f/874);r.anchorMax=new Vector2(1,1-62f/874);r.offsetMin=r.offsetMax=Vector2.zero;}yield return new WaitForSecondsRealtime(.15f);WorkshopTests.Capture(402,874,Images+"/labor-simulated-notch-"+lang+"-402.png");}}
 }
